/** Inputs used for targeting and deterministic rollout assignment. */
export type FlagContext = {
	userId?: string;
	sessionId?: string;
	email?: string;
	tags?: string[];
};

/** Rules are combined with AND. Values within an `in` rule are combined with OR. */
export type SegmentRule = {
	field: "userId" | "email" | "tags";
	operator: "equals" | "contains" | "in";
	value: string | string[];
};

/** Transport-safe flag definition. Archived flags always evaluate to false. */
export type FeatureFlag = {
	id: string;
	key: string;
	name: string;
	description: string | null;
	type: "boolean" | "rollout" | "segment";
	enabled: boolean;
	rolloutPct: number | null;
	segments: SegmentRule[];
	tags: string[];
	archivedAt: string | null;
	createdAt: string;
	updatedAt: string;
};

/** Database representation; arrays are serialized JSON. */
export type FlagRecord = Omit<
	FeatureFlag,
	"segments" | "tags" | "archivedAt" | "createdAt" | "updatedAt"
> & {
	segments: string;
	tags: string;
	archivedAt: Date | null;
	createdAt: Date;
	updatedAt: Date;
};

/** Latest evaluation retained in the plugin's bounded in-process buffer. */
export type FlagEvaluation = {
	id: string;
	flagKey: string;
	result: boolean;
	context: FlagContext;
	timestamp: string;
};

export type { CreateFlagInput, UpdateFlagInput } from "./schemas";

import { z } from "zod";

/** Stable URL-safe key; reserved JavaScript property names cannot become bulk keys. */
export const flagKeySchema = z
	.string()
	.min(1)
	.max(100)
	.regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/)
	.refine(
		(key) => !["new", "constructor", "prototype"].includes(key),
		"Choose another flag key",
	);
export const flagContextSchema = z.object({
	userId: z.string().min(1).max(256).optional(),
	sessionId: z.string().min(1).max(256).optional(),
	email: z.email().max(320).optional(),
	tags: z.array(z.string().min(1).max(100)).max(100).optional(),
});
export const segmentRuleSchema = z
	.object({
		field: z.enum(["userId", "email", "tags"]),
		operator: z.enum(["equals", "contains", "in"]),
		value: z.union([
			z.string().min(1).max(320),
			z.array(z.string().min(1).max(320)).min(1).max(100),
		]),
	})
	.superRefine((rule, ctx) => {
		if (
			rule.operator === "in"
				? !Array.isArray(rule.value)
				: typeof rule.value !== "string"
		)
			ctx.addIssue({
				code: "custom",
				path: ["value"],
				message:
					rule.operator === "in"
						? "Provide a list of values"
						: "Provide one value",
			});
		if (
			(rule.field === "tags" && rule.operator === "equals") ||
			(rule.field !== "tags" && rule.operator === "contains")
		)
			ctx.addIssue({
				code: "custom",
				path: ["operator"],
				message:
					"Use equals or in for users and emails; contains or in for tags",
			});
	});
const flagFields = z.object({
	name: z.string().trim().min(1).max(200),
	description: z.string().max(2000).nullable().optional(),
	type: z.enum(["boolean", "rollout", "segment"]).default("boolean"),
	enabled: z.boolean().default(false),
	rolloutPct: z.number().finite().min(0).max(100).nullable().optional(),
	segments: z.array(segmentRuleSchema).max(50).default([]),
	tags: z.array(z.string().trim().min(1).max(100)).max(50).default([]),
});
export const flagConfigurationSchema = flagFields.superRefine((flag, ctx) => {
	if (flag.type === "rollout" && flag.rolloutPct == null)
		ctx.addIssue({
			code: "custom",
			path: ["rolloutPct"],
			message: "A rollout percentage is required",
		});
	if (flag.type === "segment" && !flag.segments.length)
		ctx.addIssue({
			code: "custom",
			path: ["segments"],
			message: "Add at least one targeting rule",
		});
});
export const createFlagSchema = flagFields
	.extend({ key: flagKeySchema })
	.superRefine((flag, ctx) => {
		const parsed = flagConfigurationSchema.safeParse(flag);
		if (!parsed.success)
			for (const issue of parsed.error.issues)
				ctx.addIssue({
					code: "custom",
					path: issue.path,
					message: issue.message,
				});
	});
export const updateFlagSchema = z
	.object({
		...flagFields.shape,
		type: flagFields.shape.type.removeDefault(),
		enabled: flagFields.shape.enabled.removeDefault(),
		segments: flagFields.shape.segments.removeDefault(),
		tags: flagFields.shape.tags.removeDefault(),
	})
	.partial()
	.strict();
export const keySchema = z.object({ key: flagKeySchema });
export const listFlagsSchema = z.object({
	includeArchived: z
		.union([
			z.boolean(),
			z.enum(["true", "false"]).transform((value) => value === "true"),
		])
		.default(false),
});
export const evaluateSchema = keySchema.extend({
	context: flagContextSchema.optional(),
});
export const evaluateAllSchema = z.object({
	context: flagContextSchema.optional(),
});
/** Bounded base64 UTF-8 JSON, accepted by both evaluation endpoints. */
export const evaluationQuerySchema = z.object({
	context: z.string().max(32768).optional(),
});

export type CreateFlagInput = z.input<typeof createFlagSchema>;
export type UpdateFlagInput = z.input<typeof updateFlagSchema>;

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";

const key = z.object({ key: z.string() });
/** Separate management/log access from browser-visible evaluation results. */
export const featureFlagsPermissions = definePermissions("featureFlags", {
	flags: {
		read: permission(z.object({ key: z.string().optional() })),
		create: permission(key),
		update: permission(key),
		toggle: permission(key),
		archive: permission(key),
	},
	evaluations: {
		read: permission(key),
		evaluate: permission(
			z.object({
				scope: z.enum(["single", "all"]),
				key: z.string().optional(),
			}),
		),
	},
});

"use client";

import { lazy, useEffect, useState, type ReactNode } from "react";
import { ComposedRoute } from "@btst/stack/client/components";
import { featureFlagsPermissions } from "../../permissions";
import { FlagsError, FlagsLoading, FlagsNotFound } from "./shared";

const Flags = lazy(() =>
	import("./pages/flags-page.internal").then((module) => ({
		default: module.FlagsPage,
	})),
);
const Editor = lazy(() =>
	import("./pages/edit-flag-page.internal").then((module) => ({
		default: module.EditFlagPage,
	})),
);
const Log = lazy(() =>
	import("./pages/flag-detail-page.internal").then((module) => ({
		default: module.FlagDetailPage,
	})),
);

function BrowserPage({ children }: { children: ReactNode }) {
	const [mounted, setMounted] = useState(false);
	useEffect(() => setMounted(true), []);
	return mounted ? children : <FlagsLoading />;
}

function FlagList() {
	return (
		<BrowserPage>
			<Flags />
		</BrowserPage>
	);
}
function FlagEditor(props: { flagKey?: string }) {
	return (
		<BrowserPage>
			<Editor {...props} />
		</BrowserPage>
	);
}
function FlagLog(props: { flagKey: string }) {
	return (
		<BrowserPage>
			<Log {...props} />
		</BrowserPage>
	);
}

const boundary = {
	ErrorComponent: FlagsError,
	LoadingComponent: FlagsLoading,
	NotFoundComponent: FlagsNotFound,
	onError: (error: Error) => console.error("[btst/feature-flags]", error),
};

/** Protected dynamic flag list with loading and error boundaries. */
export function FlagsPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/feature-flags"
			permission={featureFlagsPermissions.flags.read({})}
			PageComponent={FlagList}
		/>
	);
}
/** Create or edit a flag definition. */
export function EditFlagPageComponent({ flagKey }: { flagKey?: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={flagKey ? `/feature-flags/${flagKey}` : "/feature-flags/new"}
			{...(flagKey
				? { permission: featureFlagsPermissions.flags.read({ key: flagKey }) }
				: {})}
			PageComponent={FlagEditor}
			props={{ flagKey }}
		/>
	);
}
/** Protected recent evaluations for a flag. */
export function FlagDetailPageComponent({ flagKey }: { flagKey: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/feature-flags/${flagKey}/log`}
			permission={featureFlagsPermissions.evaluations.read({ key: flagKey })}
			PageComponent={FlagLog}
			props={{ flagKey }}
		/>
	);
}

"use client";

import { useId, useState, type FormEvent } from "react";
import { PermissionAccess, usePluginSiteNavigation } from "@btst/stack/context";
import { featureFlagsPermissions } from "../../../permissions";
import type { FeatureFlag, SegmentRule } from "../../../types";
import type { CreateFlagInput } from "../../../schemas";
import {
	useArchiveFlag,
	useCreateFlag,
	useFlagDefinition,
	useUpdateFlag,
} from "@btst/stack/plugins/feature-flags/client/hooks";
import { FEATURE_FLAGS_PLUGIN_ID } from "../../constants";
import { Field, FlagsPage, Rollout } from "../shared";

export function EditFlagPage({ flagKey }: { flagKey?: string }) {
	return flagKey ? <ExistingFlag flagKey={flagKey} /> : <FlagForm />;
}

function ExistingFlag({ flagKey }: { flagKey: string }) {
	const { data: flag } = useFlagDefinition(flagKey);
	return <FlagForm key={flagKey} flag={flag} />;
}

function FlagForm({ flag }: { flag?: FeatureFlag }) {
	const id = useId();
	const { Link, resolve, navigate } = usePluginSiteNavigation(
		FEATURE_FLAGS_PLUGIN_ID,
	);
	const create = useCreateFlag();
	const update = useUpdateFlag();
	const archive = useArchiveFlag();
	const [name, setName] = useState(flag?.name ?? "");
	const [key, setKey] = useState(flag?.key ?? "");
	const [description, setDescription] = useState(flag?.description ?? "");
	const [type, setType] = useState<FeatureFlag["type"]>(
		flag?.type ?? "boolean",
	);
	const [percent, setPercent] = useState(flag?.rolloutPct ?? 0);
	const [tags, setTags] = useState(flag?.tags.join(", ") ?? "");
	const [enabled, setEnabled] = useState(flag?.enabled ?? false);
	const [rules, setRules] = useState(() =>
		(flag?.segments ?? []).map((rule, index) => ({
			...rule,
			id: String(index),
			text: Array.isArray(rule.value) ? rule.value.join(", ") : rule.value,
		})),
	);
	const [nextRule, setNextRule] = useState(rules.length);
	const [error, setError] = useState("");
	const [message, setMessage] = useState("");
	const [confirmArchive, setConfirmArchive] = useState(false);
	const pending = create.isPending || update.isPending || archive.isPending;
	const readOnly = !!flag?.archivedAt;
	const listPath = resolve("feature-flags").href;
	const split = (value: string) => [
		...new Set(
			value
				.split(",")
				.map((item) => item.trim())
				.filter(Boolean),
		),
	];
	const save = async (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		setError("");
		setMessage("");
		if (type === "segment" && !rules.length) {
			setError("Add at least one targeting rule.");
			return;
		}
		const segments: SegmentRule[] = rules.map((rule) => ({
			field: rule.field,
			operator: rule.operator,
			value: rule.operator === "in" ? split(rule.text) : rule.text.trim(),
		}));
		const data: CreateFlagInput = {
			key,
			name,
			description,
			type,
			rolloutPct: type === "rollout" ? percent : null,
			segments: type === "segment" ? segments : [],
			tags: split(tags),
			...(flag ? {} : { enabled }),
		};
		try {
			if (flag) {
				const { key: _key, ...patch } = data;
				await update.mutateAsync({ key: flag.key, data: patch });
				setMessage("Flag saved");
			} else {
				await create.mutateAsync(data);
				await navigate("feature-flags");
			}
		} catch (caught) {
			setError(
				caught instanceof Error
					? caught.message
					: "The flag could not be saved. Try again.",
			);
		}
	};
	const archiveFlag = async () => {
		if (!flag) return;
		setError("");
		try {
			await archive.mutateAsync(flag.key);
			await navigate("feature-flags");
		} catch (caught) {
			setError(
				caught instanceof Error
					? caught.message
					: "The flag could not be archived. Try again.",
			);
		}
	};
	const changeRule = (ruleId: string, patch: Partial<(typeof rules)[number]>) =>
		setRules((current) =>
			current.map((rule) =>
				rule.id === ruleId ? { ...rule, ...patch } : rule,
			),
		);
	return (
		<FlagsPage
			title={flag ? flag.name : "New flag"}
			description={
				flag
					? "Update the audience and configuration for this feature."
					: "Give your feature a stable key, then choose who can see it."
			}
			action={<Link href={listPath}>All flags</Link>}
		>
			{readOnly && (
				<p className="ff-notice">
					This flag is archived and always evaluates to false.
				</p>
			)}
			<form onSubmit={(event) => void save(event)}>
				<fieldset className="ff-form-grid" disabled={pending || readOnly}>
					<legend className="ff-sr-only">Flag configuration</legend>
					<div className="ff-form-section">
						<h2>Flag details</h2>
						<Field id={`${id}-name`} label="Name">
							<input
								id={`${id}-name`}
								required
								maxLength={200}
								value={name}
								onChange={(event) => setName(event.target.value)}
								placeholder="New checkout"
							/>
						</Field>
						<Field
							id={`${id}-key`}
							label="Key"
							hint="Use lowercase letters, numbers, and hyphens. The key cannot change later."
						>
							<input
								id={`${id}-key`}
								aria-describedby={`${id}-key-hint`}
								required
								pattern="[a-z0-9]+(-[a-z0-9]+)*"
								maxLength={100}
								readOnly={!!flag}
								value={key}
								onChange={(event) => setKey(event.target.value)}
								placeholder="new-checkout"
							/>
						</Field>
						<Field id={`${id}-description`} label="Description">
							<textarea
								id={`${id}-description`}
								maxLength={2000}
								rows={3}
								value={description}
								onChange={(event) => setDescription(event.target.value)}
								placeholder="What does this flag control?"
							/>
						</Field>
						<Field
							id={`${id}-tags`}
							label="Tags"
							hint="Separate tags with commas to organize your flags."
						>
							<input
								id={`${id}-tags`}
								aria-describedby={`${id}-tags-hint`}
								value={tags}
								onChange={(event) => setTags(event.target.value)}
								placeholder="beta, checkout"
							/>
						</Field>
					</div>
					<div className="ff-form-section">
						<h2>Delivery</h2>
						<Field id={`${id}-type`} label="Flag type">
							<select
								id={`${id}-type`}
								value={type}
								onChange={(event) =>
									setType(event.target.value as FeatureFlag["type"])
								}
							>
								<option value="boolean">Boolean</option>
								<option value="rollout">Percentage rollout</option>
								<option value="segment">Segment targeting</option>
							</select>
						</Field>
						{type === "boolean" && (
							<p className="ff-explanation">
								When enabled, this flag is true for everyone. Disable it at any
								time from the flag list.
							</p>
						)}
						{type === "rollout" && (
							<>
								<Field
									id={`${id}-percent`}
									label="Rollout percentage"
									hint="The same user or session stays in the same rollout group."
								>
									<input
										id={`${id}-percent`}
										type="number"
										min={0}
										max={100}
										step="any"
										required
										value={percent}
										onChange={(event) => setPercent(event.target.valueAsNumber)}
										aria-describedby={`${id}-percent-hint`}
									/>
								</Field>
								<Rollout percent={Number.isFinite(percent) ? percent : 0} />
							</>
						)}
						{type === "segment" && (
							<div className="ff-rules">
								<p className="ff-note">
									All rules must match. “Is one of” accepts comma-separated
									values.
								</p>
								{rules.map((rule, index) => (
									<fieldset key={rule.id} className="ff-rule">
										<legend>Rule {index + 1}</legend>
										<label>
											Field
											<select
												value={rule.field}
												onChange={(event) => {
													const field = event.target
														.value as SegmentRule["field"];
													changeRule(rule.id, {
														field,
														operator: field === "tags" ? "contains" : "equals",
													});
												}}
											>
												<option value="userId">User ID</option>
												<option value="email">Email</option>
												<option value="tags">Tags</option>
											</select>
										</label>
										<label>
											Match
											<select
												value={rule.operator}
												onChange={(event) =>
													changeRule(rule.id, {
														operator: event.target
															.value as SegmentRule["operator"],
													})
												}
											>
												<option
													value={rule.field === "tags" ? "contains" : "equals"}
												>
													{rule.field === "tags" ? "Contains" : "Equals"}
												</option>
												<option value="in">Is one of</option>
											</select>
										</label>
										<label>
											Value
											<input
												required
												maxLength={32000}
												value={rule.text}
												onChange={(event) =>
													changeRule(rule.id, { text: event.target.value })
												}
											/>
										</label>
										<button
											type="button"
											onClick={() =>
												setRules((current) =>
													current.filter((item) => item.id !== rule.id),
												)
											}
											aria-label={`Remove rule ${index + 1}`}
										>
											Remove
										</button>
									</fieldset>
								))}
								<button
									type="button"
									onClick={() => {
										setRules((current) => [
											...current,
											{
												id: String(nextRule),
												field: "userId",
												operator: "equals",
												value: "",
												text: "",
											},
										]);
										setNextRule((current) => current + 1);
									}}
									disabled={rules.length >= 50}
								>
									Add rule
								</button>
							</div>
						)}
						{!flag && (
							<label className="ff-checkbox">
								<input
									type="checkbox"
									checked={enabled}
									onChange={(event) => setEnabled(event.target.checked)}
								/>
								Enable on creation
							</label>
						)}
					</div>
				</fieldset>
				{error && (
					<p role="alert" className="ff-error">
						{error}
					</p>
				)}
				{message && (
					<p role="status" className="ff-success">
						{message}
					</p>
				)}
				<div className="ff-form-footer">
					<div className="ff-actions">
						{!readOnly && (
							<PermissionAccess
								permission={
									flag
										? featureFlagsPermissions.flags.update({ key: flag.key })
										: featureFlagsPermissions.flags.create({ key })
								}
							>
								<button className="ff-primary" type="submit" disabled={pending}>
									{pending ? "Saving…" : flag ? "Save changes" : "Create flag"}
								</button>
							</PermissionAccess>
						)}
						<Link href={listPath}>Cancel</Link>
					</div>
					{flag && !readOnly && (
						<PermissionAccess
							permission={featureFlagsPermissions.flags.archive({
								key: flag.key,
							})}
						>
							<button
								type="button"
								disabled={pending}
								onClick={() => setConfirmArchive(true)}
							>
								Archive flag
							</button>
						</PermissionAccess>
					)}
				</div>
			</form>
			{confirmArchive && (
				<div className="ff-notice" role="alert">
					<h2>Archive {flag?.name}?</h2>
					<p>
						Archived flags always evaluate to false. Its key remains reserved.
					</p>
					<div className="ff-actions">
						<button
							type="button"
							disabled={pending}
							onClick={() => void archiveFlag()}
						>
							Confirm archive
						</button>
						<button type="button" onClick={() => setConfirmArchive(false)}>
							Keep flag
						</button>
					</div>
				</div>
			)}
		</FlagsPage>
	);
}

"use client";

import { useEffect, useId, useState, type FormEvent } from "react";
import { PermissionAccess, usePluginSiteNavigation } from "@btst/stack/context";
import { featureFlagsPermissions } from "../../../permissions";
import type { FlagContext } from "../../../types";
import { useFlag, useFlagEvaluations } from "@btst/stack/plugins/feature-flags/client/hooks";
import { FEATURE_FLAGS_PLUGIN_ID } from "../../constants";
import { Field, FlagsPage } from "../shared";

export function FlagDetailPage({ flagKey }: { flagKey: string }) {
	const { Link, resolve } = usePluginSiteNavigation(FEATURE_FLAGS_PLUGIN_ID);
	const {
		data: evaluations,
		refetch,
		isFetching,
	} = useFlagEvaluations(flagKey);
	return (
		<FlagsPage
			title="Evaluation log"
			description={flagKey}
			action={<Link href={resolve("feature-flags").href}>All flags</Link>}
		>
			<PermissionAccess
				permission={featureFlagsPermissions.evaluations.evaluate({
					scope: "single",
					key: flagKey,
				})}
			>
				<EvaluationPreview flagKey={flagKey} onEvaluated={refetch} />
			</PermissionAccess>
			<div className="ff-section-heading">
				<div>
					<h2>Recent evaluations</h2>
					<p className="ff-note">
						Recent results are kept in memory and reset when the server
						restarts.
					</p>
				</div>
				<button
					type="button"
					disabled={isFetching}
					onClick={() => void refetch()}
				>
					Refresh log
				</button>
			</div>
			{evaluations.length ? (
				<div className="ff-table-scroll">
					<table>
						<caption className="ff-sr-only">
							Recent evaluations for {flagKey}
						</caption>
						<thead>
							<tr>
								<th scope="col">Time</th>
								<th scope="col">Result</th>
								<th scope="col">Context</th>
							</tr>
						</thead>
						<tbody>
							{evaluations.map((evaluation) => (
								<tr key={evaluation.id}>
									<td>
										<time dateTime={evaluation.timestamp}>
											{new Date(evaluation.timestamp).toLocaleString()}
										</time>
									</td>
									<td>
										<span
											className={evaluation.result ? "ff-success" : "ff-muted"}
										>
											{String(evaluation.result)}
										</span>
									</td>
									<td>
										<code className="ff-context">
											{JSON.stringify(evaluation.context)}
										</code>
									</td>
								</tr>
							))}
						</tbody>
					</table>
				</div>
			) : (
				<div className="ff-empty">
					<h2>No evaluations yet</h2>
					<p>Evaluate this flag with a context above, or use it in your app.</p>
				</div>
			)}
		</FlagsPage>
	);
}

function EvaluationPreview({
	flagKey,
	onEvaluated,
}: {
	flagKey: string;
	onEvaluated: () => unknown;
}) {
	const id = useId();
	const [context, setContext] = useState<FlagContext>();
	const [take, setTake] = useState(0);
	const submit = (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const data = new FormData(event.currentTarget);
		const value = (key: string) => String(data.get(key) ?? "").trim();
		setContext({
			...(value("userId") ? { userId: value("userId") } : {}),
			...(value("sessionId") ? { sessionId: value("sessionId") } : {}),
			...(value("email") ? { email: value("email") } : {}),
			...(value("tags")
				? {
						tags: value("tags")
							.split(",")
							.map((tag) => tag.trim())
							.filter(Boolean),
					}
				: {}),
		});
		setTake((current) => current + 1);
	};
	return (
		<section className="ff-preview">
			<h2>Try a context</h2>
			<p className="ff-note">
				Check the live result for a user or session. This also adds an
				evaluation to the log.
			</p>
			<form onSubmit={submit}>
				<div className="ff-preview-fields">
					<Field id={`${id}-user`} label="User ID">
						<input id={`${id}-user`} name="userId" maxLength={256} />
					</Field>
					<Field id={`${id}-session`} label="Session ID">
						<input id={`${id}-session`} name="sessionId" maxLength={256} />
					</Field>
					<Field id={`${id}-email`} label="Email">
						<input
							id={`${id}-email`}
							name="email"
							type="email"
							maxLength={320}
						/>
					</Field>
					<Field id={`${id}-tags`} label="Context tags">
						<input id={`${id}-tags`} name="tags" placeholder="beta, staff" />
					</Field>
				</div>
				<div className="ff-actions">
					<button type="submit">Evaluate flag</button>
					{context && (
						<PreviewResult
							key={take}
							flagKey={flagKey}
							context={context}
							onEvaluated={onEvaluated}
						/>
					)}
				</div>
			</form>
		</section>
	);
}

function PreviewResult({
	flagKey,
	context,
	onEvaluated,
}: {
	flagKey: string;
	context: FlagContext;
	onEvaluated: () => unknown;
}) {
	const { data, isFetching, error, refetch, dataUpdatedAt } = useFlag(
		flagKey,
		context,
	);
	useEffect(() => {
		void refetch();
	}, [refetch]);
	useEffect(() => {
		if (dataUpdatedAt) onEvaluated();
	}, [dataUpdatedAt, onEvaluated]);
	return error ? (
		<p role="alert" className="ff-error">
			{error.message}
		</p>
	) : (
		<output aria-live="polite">
			{isFetching || data === undefined ? "Evaluating…" : `Result: ${data}`}
		</output>
	);
}

"use client";

import { useState } from "react";
import {
	PermissionAccess,
	usePluginOverrides,
	usePluginSiteNavigation,
} from "@btst/stack/context";
import { featureFlagsPermissions } from "../../../permissions";
import type { FeatureFlag } from "../../../types";
import { useSuspenseFlags, useToggleFlag } from "@btst/stack/plugins/feature-flags/client/hooks";
import { FEATURE_FLAGS_PLUGIN_ID } from "../../constants";
import type { FeatureFlagsPluginOverrides } from "../../overrides";
import { FlagsPage as Page, Rollout } from "../shared";

export function FlagsPage() {
	const [search, setSearch] = useState("");
	const [tag, setTag] = useState("");
	const [includeArchived, setIncludeArchived] = useState(false);
	const {
		data: flags,
		refetch,
		isFetching,
	} = useSuspenseFlags({ includeArchived });
	const { Link, resolve } = usePluginSiteNavigation(FEATURE_FLAGS_PLUGIN_ID);
	const { localization } = usePluginOverrides<FeatureFlagsPluginOverrides>(
		FEATURE_FLAGS_PLUGIN_ID,
	);
	const tags = [...new Set(flags.flatMap((flag) => flag.tags))].sort();
	const visible = flags.filter(
		(flag) =>
			(!tag || flag.tags.includes(tag)) &&
			`${flag.name} ${flag.key} ${flag.description ?? ""}`
				.toLowerCase()
				.includes(search.toLowerCase()),
	);
	return (
		<Page
			title={localization?.title ?? "Feature flags"}
			description="Control what's live. Roll out changes to the right audience."
			action={
				<Link className="ff-primary" href={resolve("feature-flags/new").href}>
					{localization?.newFlag ?? "New flag"}
				</Link>
			}
		>
			<div className="ff-toolbar">
				<label className="ff-search">
					Find a flag
					<input
						type="search"
						value={search}
						onChange={(event) => setSearch(event.target.value)}
						placeholder="Search name or key"
					/>
				</label>
				<label>
					Tag
					<select value={tag} onChange={(event) => setTag(event.target.value)}>
						<option value="">All tags</option>
						{tags.map((value) => (
							<option key={value}>{value}</option>
						))}
					</select>
				</label>
				<label className="ff-checkbox">
					<input
						type="checkbox"
						checked={includeArchived}
						onChange={(event) => setIncludeArchived(event.target.checked)}
					/>
					Show archived
				</label>
				<button
					type="button"
					disabled={isFetching}
					onClick={() => void refetch()}
				>
					Refresh flags
				</button>
			</div>
			<p className="ff-count">
				{visible.length} {visible.length === 1 ? "flag" : "flags"}
			</p>
			{visible.length ? (
				<ul className="ff-list" aria-label="Feature flags">
					{visible.map((flag) => (
						<FlagRow key={flag.key} flag={flag} />
					))}
				</ul>
			) : (
				<div className="ff-empty">
					<h2>
						{flags.length ? "No matching flags" : "Your first flag starts here"}
					</h2>
					<p>
						{flags.length
							? "Try another name, key, or tag."
							: "Create a flag to control a feature without redeploying your app."}
					</p>
				</div>
			)}
		</Page>
	);
}

function FlagRow({ flag }: { flag: FeatureFlag }) {
	const toggle = useToggleFlag();
	const { Link, resolve } = usePluginSiteNavigation(FEATURE_FLAGS_PLUGIN_ID);
	const [error, setError] = useState("");
	const change = async () => {
		setError("");
		try {
			await toggle.mutateAsync({ key: flag.key, enabled: !flag.enabled });
		} catch (caught) {
			setError(
				caught instanceof Error
					? caught.message
					: "The flag could not be changed. Try again.",
			);
		}
	};
	return (
		<li className="ff-row" data-archived={!!flag.archivedAt}>
			<div className="ff-identity">
				<Link
					href={resolve(`feature-flags/${flag.key}`).href}
					className="ff-name"
				>
					{flag.name}
				</Link>
				<code>{flag.key}</code>
				{flag.description && <p>{flag.description}</p>}
				{flag.tags.length > 0 && (
					<ul className="ff-tags" aria-label="Tags">
						{flag.tags.map((tag) => (
							<li key={tag}>{tag}</li>
						))}
					</ul>
				)}
			</div>
			<div className="ff-audience">
				{flag.type === "rollout" ? (
					<Rollout percent={flag.rolloutPct ?? 0} />
				) : (
					<>
						<span>
							{flag.type === "segment" ? "Segment targeting" : "Boolean"}
						</span>
						<p>
							{flag.type === "segment"
								? `${flag.segments.length} targeting ${flag.segments.length === 1 ? "rule" : "rules"}`
								: "Everyone when enabled"}
						</p>
					</>
				)}
			</div>
			<div className="ff-row-actions">
				{flag.archivedAt ? (
					<span className="ff-muted">Archived</span>
				) : (
					<PermissionAccess
						permission={featureFlagsPermissions.flags.toggle({ key: flag.key })}
					>
						<button
							type="button"
							className="ff-toggle"
							role="switch"
							aria-label={`Enable ${flag.name}`}
							aria-checked={flag.enabled}
							disabled={toggle.isPending}
							onClick={() => void change()}
						>
							<span aria-hidden="true" />
							{flag.enabled ? "Enabled" : "Disabled"}
						</button>
					</PermissionAccess>
				)}
				<PermissionAccess
					permission={featureFlagsPermissions.evaluations.read({
						key: flag.key,
					})}
				>
					<Link href={resolve(`feature-flags/${flag.key}/log`).href}>
						Evaluation log
					</Link>
				</PermissionAccess>
			</div>
			{error && (
				<p role="alert" className="ff-error">
					{error}
				</p>
			)}
		</li>
	);
}

